import React, { useState } from "react";

function Malware() {
  const [filename, setFilename] = useState("");
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);

  const checkFile = async () => {
    try {
      const token =
        localStorage.getItem(
          "access_token"
        );

      setLoading(true);

      const response = await fetch(
        "http://127.0.0.1:8000/malware/scan",
        {
          method: "POST",
          headers: {
            "Content-Type":
              "application/json",
            Authorization:
              `Bearer ${token}`
          },
          body: JSON.stringify({
            filename
          })
        }
      );

      const data =
        await response.json();

      setResult(data);

      // Stop loading after response
      setLoading(false);

    } catch (error) {
      console.error(error);

      // Stop loading if error happens
      setLoading(false);
    }
  };

  return (
    <div style={styles.main}>
      <h1>Malware Analysis</h1>

      <input
        style={styles.input}
        value={filename}
        onChange={(e) =>
          setFilename(
            e.target.value
          )
        }
        placeholder="Enter filename"
      />

      <button
        onClick={checkFile}
        style={styles.button}
      >
        Analyze
      </button>

      {/* Loading message */}
      {loading && (
        <p style={styles.loading}>
          Scanning...
        </p>
      )}

      {result && (
        <div style={styles.result}>
          <pre>
            {JSON.stringify(
              result,
              null,
              2
            )}
          </pre>
        </div>
      )}
    </div>
  );
}

const styles = {
  main: {
    flex: 1,
    padding: "30px",
    color: "white"
  },

  input: {
    padding: "12px",
    width: "300px",
    borderRadius: "8px",
    border: "none",
    marginRight: "10px"
  },

  button: {
    padding: "12px 20px",
    border: "none",
    borderRadius: "8px",
    background: "#10b981",
    color: "white",
    fontWeight: "bold",
    cursor: "pointer"
  },

  loading: {
    marginTop: "15px",
    color: "#facc15",
    fontWeight: "bold"
  },

  result: {
    marginTop: "20px",
    background: "#1e293b",
    padding: "20px",
    borderRadius: "10px"
  }
};

export default Malware;
